const tools = [
 {id:'cursor',name:'Cursor',symbol:'◈',subtitle:'Code & build',state:'empty',title:'A clear place to start',copy:'Your next build belongs here. Choose a workspace when real app access is available.'},
 {id:'claude',name:'Claude',symbol:'✳',subtitle:'Think & explore',state:'stale',title:'Shape the dashboard experience',copy:'Demo conversation · What makes a workspace feel like home?'},
 {id:'chatgpt',name:'ChatGPT',symbol:'◎',subtitle:'Research & make',state:'disconnected',title:'Waiting for a connection',copy:'Home cannot read your conversations. Your ChatGPT app remains its own workspace.'},
 {id:'hermes',name:'Hermes',symbol:'☿',subtitle:'Run & coordinate',state:'unavailable',title:'Session access unavailable',copy:'No supported session interface is configured. Opening and controlling Hermes are separate capabilities.'}
];
const defaults=()=>({selected:'cursor',focused:null,collapsed:[],order:tools.map(t=>t.id),left:69,row:50,tile:50,scene:'mixed'});
let state=defaults();
try{let s=JSON.parse(localStorage.getItem('coltons-home-prototype-v1'));if(s&&Array.isArray(s.order)&&s.order.length===4&&new Set(s.order).size===4&&s.order.every(id=>tools.some(t=>t.id===id))){state={...state,...s};if(![...tools.map(t=>t.id),'usage'].includes(state.selected))state.selected='cursor';if(![null,...tools.map(t=>t.id),'usage'].includes(state.focused))state.focused=null;state.collapsed=Array.isArray(s.collapsed)?s.collapsed.filter(id=>[...tools.map(t=>t.id),'usage'].includes(id)):[];for(let key of ['left','row','tile'])state[key]=Math.min(key==='left'?78:65,Math.max(key==='left'?54:35,Number(state[key])||defaults()[key]));if(!['mixed','empty','disconnected','stale','unavailable'].includes(state.scene))state.scene='mixed';}}catch{}
const $=s=>document.querySelector(s);
function save(){try{localStorage.setItem('coltons-home-prototype-v1',JSON.stringify(state));}catch{}}
const statuses={empty:['Empty','off'],stale:['Stale','warn'],disconnected:['Disconnected','warn'],unavailable:['Unavailable','off']};
function controls(id){return `<div class="pane-controls"><button class="icon-button" data-action="focus" data-id="${id}" aria-label="${state.focused===id?'Unfocus':'Focus'} ${id} pane" title="Focus pane">${state.focused===id?'⊡':'⤢'}</button><button class="icon-button" data-action="collapse" data-id="${id}" aria-label="${state.collapsed.includes(id)?'Expand':'Collapse'} ${id} pane" title="Collapse pane">${state.collapsed.includes(id)?'+':'−'}</button></div>`;}
function render(){
 document.documentElement.style.setProperty('--left',state.left+'%');document.documentElement.style.setProperty('--row',state.row+'%');document.documentElement.style.setProperty('--tile',state.tile+'%');
 $('#scene').value=state.scene;
 $('#tool-nav').innerHTML=tools.map((t,i)=>`<button class="nav-tool ${state.selected===t.id?'active':''}" data-action="select" data-id="${t.id}" aria-label="Select ${t.name} pane" aria-pressed="${state.selected===t.id}"><span class="tool-symbol ${t.id}">${t.symbol}</span><span>${t.name}</span><kbd>⌘ ${i+1}</kbd></button>`).join('')+`<button class="nav-tool ${state.selected==='usage'?'active':''}" data-action="select" data-id="usage" aria-label="Select Model usage pane" aria-pressed="${state.selected==='usage'}"><span class="tool-symbol">≋</span><span>Model usage</span><kbd>⌘ 5</kbd></button>`;
 $('#tools-grid').innerHTML=state.order.map((id,i)=>{const t=tools.find(t=>t.id===id),s=state.scene==='mixed'?t.state:state.scene;const [label,tone]=statuses[s];let content;
 if(s==='stale')content=`<div class="caps">LAST OBSERVATION · DEMO</div><div class="session"><div class="session-head"><span>${t.id==='claude'?t.title:'Example workspace'}</span><span class="caps">DEMO</span></div><p>${t.id==='claude'?t.copy:'A sample context for evaluating this pane.'}</p><div class="session-sub">Oct 6, 2026 · 8:40 AM CDT</div></div>`;
 else{const copy=s==='empty'?['A clear place to start','No sessions added. This space is ready for a future, supported app connection.']:s==='disconnected'?['Waiting for a connection','Home has no connection to this tool. Preview its destination without opening an app.']:['Session access unavailable','No verified session interface is configured. App access will be evaluated in a later stage.'];content=`<div class="state-content"><h3>${copy[0]}</h3><p>${copy[1]}</p></div>`;}
 return `<section id="pane-${id}" class="pane tool-pane ${state.selected===id?'selected':''} ${state.collapsed.includes(id)?'collapsed':''}" style="grid-column:${i%2?3:1};grid-row:${i<2?1:3}" tabindex="0" aria-label="${t.name} pane"><div class="pane-header"><span class="tool-symbol ${id}">${t.symbol}</span><div class="pane-title"><h2>${t.name}</h2><small>${t.subtitle}</small></div>${controls(id)}</div><div class="pane-body"><div class="status-line"><span class="status ${tone}">Demo · ${label}</span><span>${s==='stale'?'Last seen 8:40 AM CDT':'No live integration'}</span></div>${content}</div><div class="pane-bottom"><span>${s==='stale'?'Old fixture · not live activity':'External app destination'}</span><button class="open-button" data-action="open" data-id="${id}">Open ${t.name} · preview ↗</button></div></section>`;
 }).join('')+`<div class="splitter tile-split" role="separator" aria-label="Resize tool pane columns" aria-orientation="vertical" aria-valuemin="35" aria-valuemax="65" aria-valuenow="${state.tile}" tabindex="0" data-size="tile"></div><div class="splitter row-split" role="separator" aria-label="Resize tool pane rows" aria-orientation="horizontal" aria-valuemin="35" aria-valuemax="65" aria-valuenow="${state.row}" tabindex="0" data-size="row"></div>`;
 renderUsage();
 $('#workspace').classList.toggle('focused',!!state.focused);
 $('#workspace').classList.toggle('usage-selected',state.selected==='usage');
 $('#workspace').classList.toggle('usage-focused',state.focused==='usage');
 document.querySelectorAll('.pane').forEach(p=>{const id=p.id==='usage'?'usage':p.id.slice(5);p.classList.toggle('hidden',!!state.focused&&id!==state.focused);p.classList.toggle('mobile-hidden',id!==state.selected);});
 $('#layout-label').textContent=state.focused?'Focus view':`${5-state.collapsed.length} expanded · ${state.collapsed.length} collapsed`;
 $('#column-split').setAttribute('aria-valuenow',state.left);save();
}
function renderUsage(){let mode=state.scene;const blank=['empty','disconnected','unavailable'].includes(mode);$('#usage').className=`pane usage-pane ${state.selected==='usage'?'selected':''} ${state.collapsed.includes('usage')?'collapsed':''}`;$('#usage').innerHTML=`<div class="pane-header"><span class="usage-icon">≋</span><div class="pane-title"><h2>Model usage</h2><small>Capacity, in one place</small></div>${controls('usage')}</div><div class="usage-intro"><span class="demo-tag">ALL VALUES ARE DEMO</span><p>Separate products. Separate windows.<br>A shared view without a blended score.</p></div><div class="usage-content">${blank?`<div class="usage-row"><span class="status ${mode==='disconnected'?'warn':'off'}">Demo · ${statuses[mode][0]}</span><div class="state-content"><h3 style="margin-top:20px">${mode==='empty'?'No usage sources yet':mode==='disconnected'?'Sources disconnected':'Usage not available'}</h3><p>${mode==='empty'?'Add a source in a future stage.':mode==='disconnected'?'No recent observation. Retry only reloads demo fixtures.':'No verified API is configured for these accounts.'} Missing values are unknown, never zero.</p></div><div class="metric"><span>Subscription capacity</span><strong>Unknown</strong></div><div class="metric"><span>API spend</span><strong>Unknown</strong></div></div>`:`<div class="usage-row"><div class="usage-heading">Anthropic <span>DEMO ${mode==='stale'?'· STALE':'· MANUAL'}</span></div><div class="account">Example personal account / Claude subscription</div><div class="metric"><span>5-hour window</span><strong>68% remaining</strong></div><div class="meter"><span style="width:68%"></span></div><div class="metric-foot">Demo reset · Oct 6, 1:00 PM CDT</div><div class="metric"><span>Weekly window</span><strong>42% remaining</strong></div><div class="meter gold"><span style="width:42%"></span></div><div class="metric-foot">Demo reset · Oct 9, 9:00 AM CDT<br>Fixture snapshot · Oct 6, 8:40 AM CDT</div></div><div class="usage-row"><div class="usage-heading">OpenAI <span>DEMO · UNAVAILABLE</span></div><div class="account">Example personal account / ChatGPT subscription</div><div class="metric"><span>Plan capacity</span><strong>Unknown</strong></div><div class="metric-foot">No verified subscription source configured.</div></div><div class="usage-row"><div class="usage-heading">OpenAI API <span>DEMO ${mode==='stale'?'· STALE':'· MANUAL'}</span></div><div class="account">Example organization / API billing · USD</div><div><span class="money">$12.40</span><span class="caps">THIS MONTH</span></div><div class="metric-foot">Oct 1–31, 2026 · America/Chicago<br>Fixture snapshot · Oct 6, 8:40 AM CDT<br>Spend only · no budget or token estimate</div></div>`}<div class="source-note">${mode==='stale'?'Stale demo snapshots remain visible. A failed source never becomes a zero reading.':'Prototype coverage: 0 live sources. Fixtures illustrate the layout; they are not your accounts or limits.'}</div></div><div class="pane-bottom"><span>America/Chicago · CDT</span><button data-action="refresh" class="icon-button" style="font-size:10px">↻ Refresh demo</button></div>`;}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function select(id){state.selected=id;if(state.focused)state.focused=id;state.collapsed=state.collapsed.filter(x=>x!==id);render();(id==='usage'?$('#usage'):$(`#pane-${id}`)).focus();}
function focus(id){state.focused=state.focused===id?null:id;state.selected=id;state.collapsed=state.collapsed.filter(x=>x!==id);render();(id==='usage'?$('#usage'):$(`#pane-${id}`)).focus();}
function reset(){state={...defaults(),scene:state.scene};render();notify('Default arrangement restored.');}
function preview(id){const t=tools.find(t=>t.id===id);$('#preview-title').textContent=`Open ${t.name}`;$('#preview-copy').textContent=`In the future Mac app, this would open or focus ${t.name}. This preview does not launch it, read its sessions, or send input.`;$('#preview').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;let id=b.dataset.id;switch(b.dataset.action){case 'select':select(id);break;case 'focus':focus(id);break;case 'collapse':state.collapsed=state.collapsed.includes(id)?state.collapsed.filter(x=>x!==id):[...state.collapsed,id];if(state.focused===id)state.focused=null;render();document.querySelector(`[data-action="collapse"][data-id="${id}"]`).focus();break;case 'open':preview(id);break;case 'refresh':notify('Demo fixtures reloaded. No provider was contacted.');break;}});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));
$('#scene').addEventListener('change',e=>{state.scene=e.target.value;render();notify('Demo scenario: '+e.target.options[e.target.selectedIndex].text);});$('#restore').onclick=reset;$('#swap').onclick=()=>{state.order=[...state.order.slice(2),...state.order.slice(0,2)];render();notify('Tool rows swapped.');};$('#home').onclick=()=>{state.focused=null;render();$('#workspace').focus();};
let commandIndex=0,filtered=[];const commands=[...tools.flatMap((t,i)=>[{name:`Select ${t.name}`,hint:`⌘ ${i+1}`,run:()=>select(t.id)},{name:`Focus ${t.name}`,hint:'Layout',run:()=>focus(t.id)},{name:`Open ${t.name} · preview`,hint:'Preview only',run:()=>preview(t.id)}]),{name:'Select Model usage',hint:'⌘ 5',run:()=>select('usage')},{name:'Focus Model usage',hint:'Layout',run:()=>focus('usage')},{name:'Restore default arrangement',hint:'Layout',run:reset},{name:'Return Home',hint:'⌘ 0',run:()=>{state.focused=null;render();}},{name:'Refresh demo usage',hint:'Demo only',run:()=>notify('Demo fixtures reloaded. No provider was contacted.')}];
function commandRender(){filtered=commands.filter(c=>c.name.toLowerCase().includes($('#search').value.toLowerCase()));commandIndex=Math.max(0,Math.min(commandIndex,filtered.length-1));$('#commands').innerHTML=filtered.length?filtered.map((c,i)=>`<button class="command ${i===commandIndex?'active':''}" data-command="${i}">${c.name}<span>${c.hint}</span></button>`).join(''):'<p style="padding:12px;color:var(--muted)">No matching commands.</p>';}
function openPalette(){commandIndex=0;$('#search').value='';commandRender();$('#palette').showModal();$('#search').focus();}$('#palette-launch').onclick=openPalette;$('#search').oninput=()=>{commandIndex=0;commandRender();};$('#commands').onclick=e=>{const b=e.target.closest('[data-command]');if(b){$('#palette').close();filtered[Number(b.dataset.command)].run();}};
$('#palette').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+filtered.length)%Math.max(1,filtered.length);commandRender();$('#commands .active')?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&filtered.length){e.preventDefault();$('#palette').close();filtered[commandIndex].run();}});
document.addEventListener('keydown',e=>{const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#preview').open)openPalette();return;}if($('#palette').open||$('#preview').open)return;if(mod&&/^[0-5]$/.test(e.key)){e.preventDefault();if(e.key==='0'){state.focused=null;render();$('#workspace').focus();}else select([...tools.map(t=>t.id),'usage'][Number(e.key)-1]);}if(e.key==='Escape'){state.focused=null;render();$('#workspace').focus();}});
function resize(key,value){state[key]=Math.round(Math.max(key==='left'?54:35,Math.min(key==='left'?78:65,value)));document.documentElement.style.setProperty('--'+key,state[key]+'%');const el=key==='left'?$('#column-split'):document.querySelector(`[data-size="${key}"]`);el?.setAttribute('aria-valuenow',state[key]);save();}
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.splitter,#column-split');if(!el)return;const key=el.dataset.size||'left',rect=(key==='left'?$('#workspace'):$('#tools-grid')).getBoundingClientRect();el.setPointerCapture(e.pointerId);const move=ev=>resize(key,key==='row'?(ev.clientY-rect.top)/rect.height*100:(ev.clientX-rect.left)/rect.width*100);const up=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);});
document.addEventListener('keydown',e=>{if(!e.target.matches('.splitter,#column-split'))return;const key=e.target.dataset.size||'left',negative=key==='row'?'ArrowUp':'ArrowLeft',positive=key==='row'?'ArrowDown':'ArrowRight';if(e.key===negative||e.key===positive){e.preventDefault();resize(key,state[key]+(e.key===negative?-2:2));}});
render();
